1	// Pure, DOM-free "what should be visually marked" decision logic for the
2	// live-editing matrix view (Phase 5 of
3	// residual/iterations/view-live-editing-plan.md). render.ts (untested,
4	// DOM-wiring code, closed out via manual browser verification per the plan)
5	// is the only consumer of this module's output — it mutates the DOM, this
6	// module never does.
7	//
8	// Builds directly on web/src/model.ts (Phase 4, stable): imports
9	// `PendingState`, `computeStateValidity`, and the snapshot types rather than
10	// redefining or duplicating any of that.
11	
12	import { computeStateValidity, type PendingState } from "./model.ts";
13	
14	/**
15	 * Which sticky axes (row labels / component-column headers) should be
16	 * rendered invalid.
17	 *
18	 * Scoping decision (documented per instructions): the plan's Phase 5 line
19	 * ("red state ... propagated to the sticky header cell (column) and sticky
20	 * label cell (row) for any invalid cell's axis") reads, taken literally, as
21	 * if individual NKP *cells* can be invalid and blame a specific component
22	 * column. But the NKP matrix has no per-cell required/optional concept — a
23	 * cell is only ever "coupled" or "not coupled" (see model.ts's
24	 * `computeStateValidity`, which validates required *text* fields plus a
25	 * row-wide "zero components toggled" rule, never a specific force×component
26	 * pair). The only per-row invalidity that touches the matrix at all is that
27	 * whole-row "zero components" rule, and it does not implicate any single
28	 * column over another — every column is equally "missing" for that row.
29	 *
30	 * So `invalidComponentColumns` is scoped narrowly: it stays empty for the
31	 * "zero components toggled" case (there is no literal per-cell reading that
32	 * applies), and would only ever be populated by a genuine per-cell invalid
33	 * state, which does not exist in this domain today. This is a deliberate
34	 * narrowing of the spec, not an oversight — see
35	 * render-decisions.test.ts's "invalidComponentColumns" describe block for
36	 * the cases this claim is tested against.
37	 */
38	export interface InvalidMarks {
39	  /** Force keys (real id or tempId) whose sticky row label should be marked invalid. */
40	  invalidForceKeys: Set<string>;
41	  /** Component names whose sticky column header should be marked invalid. Always empty today — see module docs. */
42	  invalidComponentColumns: Set<string>;
43	}
44	
45	/**
46	 * Computes which sticky row labels (and, in principle, column headers) need
47	 * invalid-marking for the current PendingState. Delegates all validity
48	 * business rules to `computeStateValidity` from model.ts — this function
49	 * does not reimplement or re-decide what makes a force invalid, it only
50	 * reshapes that verdict into a marking decision.
51	 */
52	export function computeInvalidMarks(state: PendingState): InvalidMarks {
53	  const { invalidForceIds } = computeStateValidity(state);
54	  return {
55	    invalidForceKeys: new Set(invalidForceIds),
56	    invalidComponentColumns: new Set(),
57	  };
58	}
59	
60	/** Options controlling which components are visible in the rendered matrix. */
61	export interface VisibilityOptions {
62	  /** When false, components with status "proposed" are excluded. */
63	  showProposed: boolean;
64	  /** When false, components unrelated to `filteredForceIds` are excluded. */
65	  showUnrelated: boolean;
66	  /**
67	   * Restricts the "related" check to this set of force ids/tempIds.
68	   * `null` means no filter is active, i.e. "related" is checked against
69	   * every force (base + added) in the state.
70	   */
71	  filteredForceIds: string[] | null;
72	}
73	
74	/**
75	 * Returns the component names that should be rendered as matrix columns,
76	 * in a stable order, given the current PendingState and visibility toggles.
77	 * Considers both `state.baseComponents` and `state.addedComponents`, and
78	 * (for the "unrelated" filter) each force's base-merged-with-pending-update
79	 * component list — mirroring the same merge model.ts's
80	 * `computeStateValidity` performs internally, without duplicating its
81	 * validity business rules.
82	 */
83	export function visibleComponents(state: PendingState, options: VisibilityOptions): string[] {
84	  const all = [...state.baseComponents, ...state.addedComponents];
85	  const filtered = options.showProposed ? all : all.filter((c) => c.status !== "proposed");
86	
87	  if (options.showUnrelated) {
88	    return filtered.map((c) => c.name);
89	  }
90	
91	  const relevantBaseForces = state.baseForces.filter(
92	    (f) => options.filteredForceIds === null || options.filteredForceIds.includes(f.id),
93	  );
94	  const relevantAddedForces = state.addedForces.filter(
95	    (f) => options.filteredForceIds === null || options.filteredForceIds.includes(f.tempId),
96	  );
97	
98	  const relatedComponentNames = new Set<string>();
99	  for (const base of relevantBaseForces) {
100	    const update = state.updatedForces[base.id];
101	    const components = update?.components ?? base.components;
102	    for (const name of components) relatedComponentNames.add(name);
103	  }
104	  for (const added of relevantAddedForces) {
105	    for (const name of added.components) relatedComponentNames.add(name);
106	  }
107	
108	  return filtered.filter((c) => relatedComponentNames.has(c.name)).map((c) => c.name);
109	}
110	
111	/** One entry in the attractor `<select>` dropdown. */
112	export interface AttractorOption {
113	  id: string;
114	  name: string;
115	}
116	
117	/**
118	 * Merges `state.baseAttractors` with `state.addedAttractors` (attractors
119	 * added this session, not yet part of the base snapshot) into a single
120	 * sorted-by-name list of dropdown options.
121	 */
122	export function attractorOptions(state: PendingState): AttractorOption[] {
123	  const all = [...state.baseAttractors, ...state.addedAttractors];
124	  return all
125	    .map((a) => ({ id: a.id, name: a.name }))
126	    .sort((a, b) => a.name.localeCompare(b.name));
127	}
